ee:variables.ee:set-variable:
%dw 2.0
import * from dw::util::Timer
output application/json
---
/* Please remove this if this transformation is not required final 
 * transformation to convert to e-commerce system request should be 
 * taken place at system api level */

{
  "id": "customercart" ++ (currentMilliseconds()[4] ++ currentMilliseconds()[5] ++ currentMilliseconds()[2]),
  "currency": "USD",
  "line_items": [
    {
      "id": "1",
      "item": {
        "id": payload.line_items[0].item.id,
        "title": "Sony Products",
        "price": 27999 + currentMilliseconds()[4]
      },
      "quantity": 1,
      "totals": [
        {
          "type": "total",
          "amount": 27999 + currentMilliseconds()[4]
        }
      ]
    }
  ],
  "totals": [
    {
      "type": "total",
      "amount": 27999 + currentMilliseconds()[4],
      "display_text": "Est. (tax at checkout)"
    }
  ],
  "continue_url": "https://sony.com/cart?id=cart_abc123",
  "expires_at": "2026-04-29T10:00:00Z"
}

